  Skill_125370_UnknownName = {
    Text = "Эхо поместья"
  },
  Skill_125371_AwakerSkillBackgroundStory = {
    Text = "Они никогда не говорят о её происхождении, только о той неописуемой великой радости, когда она родилась.\nТвоё сознание растает в экстазе, твоё прошлое растает в экстазе, твой череп растает в экстазе... твой мозг растает в экстазе.\nОдной лишь мягкой закуской на входе — с «тоской» в качестве приманки."
  },
  Skill_125371_BattleDesc_0 = {
    Text = "Наносит всем врагам <Damage:[Damage:Arg1]> ед. гарантированного критического урона и активирует [Arg2]% отравления. <ResonanceKeywords:Резонанс 3>: <EmbryoFusionIconKeywords:Слияние эмбриона> +[Arg4]( [Arg5]/3 )."
