  Skill_125372_Desc_1 = {
    Text = "Наносит <Damage:[Damage:Arg1]> Урон цели и врагу с <HPAndShieldMax:наибольшим ОЗ и Щитом>, накладывает 1 стак <PVPLostSoulKeyWords:Очарования>."
  },
  Skill_125372_Name_1 = {
    Text = "Трудно убить лотосовые нити"
  },
  Skill_125373_AwakerSkillBackgroundStory = {
    Text = "Зачем искушать их? Они и так бессильны сопротивляться. \n Зачем подстрекать их? Пока не достигнут высшего, более широкого, Мальстрём властолюбия охватит все, что увидят. \n Потому что лишь погрязшие в чувствах обыватели трудно перевариваются. Потому что обыденное тело, не пропитанное амбициями, совершенно неинтересно. \n Край без снов — это щедрость хищника, оставляющего добыче остатки. \n В центре радости нет ничего, только бесконечный хаос, бесконечная хитрость."
  },
  Skill_125373_Desc_0 = {
    Text = "Сюй получает <Energy:[Energy:Arg1]> единиц Алиемуса. <ExaltIconKeywords:Возвышение>: при первом срабатывании эффекта <ResonanceKeywords:Резонанса> каждой Командной карты Сюй в ходу базовый Расход Арифметики этой карты становится равным 0."
  },
  Skill_125373_Desc_15 = {
    Text = "Сюй получает <Energy:[Energy:Arg1]> единиц Алиемуса. <ExaltIconKeywords:Возвышение>: при первом срабатывании эффекта <ResonanceKeywords:Резонанса> каждой Командной карты Сюй в ходу базовый Расход Арифметики этой карты становится равным 0. Максимальное количество стаков <WitherKeywords0:Очарования> повышается до 15, первая разыгранная Командная карта Сюй в каждом ходу срабатывает дополнительно 1 раз."
  },
  Skill_125373_EffectNameList = {
