  Skill_126488_BattleDesc_0 = {
    Text = "Потеряйте [Float:Arg3]% Макс. ОЗ ([Arg4]), получите 1 Уровень<SilkKeywords:Плетельщица судеб>. В этом бою потеря ОЗ «<DerivativeCardKeywords_138:Путеводные нити>» и Урон, нанесённый Арахной<CutKeywords:Судья судьбы>, увеличивается на [Arg2]%. Ускользание: Арахна случайным образом получает от 15 до 30 очков Алиемуса."
  },
  Skill_126488_Desc_0 = {
    Text = "Потеряйте [Arg1]% Макс. ОЗ, получите 1 Уровень<SilkKeywords:Плетельщица судеб>. В этом бою потеря ОЗ «<DerivativeCardKeywords_138:Путеводные нити>» и Урон, нанесённый Арахной<CutKeywords:Судья судьбы>, увеличивается на [Arg2]%. Ускользание: Арахна случайным образом получает от 15 до 30 очков Алиемуса."
