  Skill_126488_Name = {
    Text = "Путеводные нити"
  },
  Skill_126490_AwakerSkillBackgroundStory = {
    Text = "В тот миг, когда поднялся Занавес опускается, марионетки подняли головы и увидели нежное лицо за прялкой.\nНити натянулись, и под песни и танцы марионеток она улыбнулась, как Матушка.\nВ театре судьбы она — их единственный зритель."
  },
  Skill_126490_BattleDesc_0 = {
    Text = "Арахна получает <Energy:[Energy:Arg1]> очков Алиемуса. <ExaltIconKeywords:Возвышение>: «Аннигиляция» изменена на выбор 1 карты сверхпространства, извлечение её и сделать так, чтобы она сработала 2 раза при следующем розыгрыше, чтобы следующая разыгранная Командная Карта активировала <SingularityKeywords3:Межпространственный Переход>."
  },
  Skill_126490_BattleDesc_15 = {
    Text = "Арахна получает <Energy:[Energy:Arg1]> ед. Алиемуса. <ExaltIconKeywords:Возвышение>: «Аннигиляция» заменяется на выбор 1 Командной карты из Ультра пространства для извлечения с эффектом «Срабатывает дополнительно 1 раз после следующего розыгрыша», а следующая разыгранная Командная карта активирует <SingularityKeywords3:Пространственный скачок>. После применения «Аннигиляции» немедленно нанести всем врагам <FixedDamage:Чистый урон>, равный 50% «Приговора судьбы»; Усиление урона и Повышение щита следующего Вознесения увеличиваются на 50%."
  },
  Skill_126490_Desc_0 = {
    Text = "Арахна получает [Arg2]% базового Алиемуса. <ExaltIconKeywords:Возвышение>: «Аннигиляция» изменена на выбор 1 карты сверхпространства, извлечение её и сделать так, чтобы она сработала 2 раза при следующем розыгрыше, чтобы следующая разыгранная Командная Карта активировала <SingularityKeywords3:Межпространственный Переход>."
  },
  Skill_126490_Desc_15 = {
    Text = "Арахна получает [Arg2]% Основного алиемуса. <ExaltIconKeywords:Возвышение>: «Аннигиляция» заменяется на выбор 1 Командной карты из Ультра пространства для извлечения с эффектом «Срабатывает дополнительно 1 раз после следующего розыгрыша», а следующая разыгранная Командная карта активирует <SingularityKeywords3:Пространственный скачок>. После применения «Аннигиляции» немедленно нанести всем врагам <FixedDamage:Чистый урон>, равный 50% «Приговора судьбы»; Усиление урона и Повышение щита следующего Вознесения увеличиваются на 50%."
