  },
  Skill_131857_AwakerSkillBackgroundStory = {
    Text = "До тех пор, пока не будет достигнут тот мир, который так долго искали, — мир, где больше не нужно прятаться.\nВсё, что стоит на пути, — это «враги», которых следует сокрушить."
  },
  Skill_131857_BattleDesc_0 = {
    Text = "Нанести <Damage:[Damage:Arg1]> урона. Получить <Energy:[Energy:Arg2]> очков безумия."
