  Skill_131857_BattleDesc_2 = {
    Text = "Наносит <Damage:[Damage:Arg1]> ед. урона. Получает <Energy:[Energy:Arg2]> ед. безумия. <EmbryoFusionIconKeywords:Слияние эмбриона> +[Blood:Arg3]."
  },
