  Skill_132227_Name = {
    Text = "Навык@Тест@Тест определения нового глубоководного класса"
  },
  Skill_132357_AwakerSkillBackgroundStory = {
    Text = "\"Смотри! Как рыба, Орета пузырится!\""
  },
  Skill_132357_Desc = {
    Text = "Получить <Block:[Block:Arg1]> единиц Щита и применить состояния к себе, игроку и переднему ряду врагов соответственно. Значение при разыгрывании и фактическое значение применяются по 1 разу каждое."
  },
  Skill_132357_EffectNameList_0 = {
    Text = "Щит,безумие"
