  Skill_132357_Name = {
    Text = "Тест·защита"
  },
  Skill_132357_PropertyNameList_0 = {
    Text = "защита*GrowValue1,$GrowValue2"
  },
  Skill_132358_AwakerSkillBackgroundStory = {
    Text = "Девушка с грустью покинула обанкротившийся аквариум, но в качестве платы за работу ей разрешили забрать нескольких медуз домой.  \nЭто были её любимые маленькие создания — духи морских глубин, вечные цветы жизни.  \nСтоило только заботиться о них с любовью, и они могли наполнить весь аквариум! — о таком она когда-то мечтала.  ."
  },
  Skill_132358_Desc_0 = {
    Text = "Аурита получает <Energy:[Energy:Arg1]> очков алиемуса. <ExaltIconKeywords:Возвышение>: получает 1 щупальце и помещает 2 карты \"Деление стрекательных клеток\" в руку. Когда Аурита наносит Урон, [Arg2] щупальца атакуют 1 раз."
  },
  Skill_132358_Desc_15 = {
    Text = "Аурита получает <Energy:[Energy:Arg1]> очков алиемуса. <ExaltIconKeywords:Возвышение>: получите 1 щупальце и возьмите 2 карты «Деление стрекательных клеток» в руку. Когда Аурита наносит Урон, [Arg2] щупалец атакует 1 раз. «Удар» Ауриты становится пробивающим уроном и дополнительно наносит 2 урона."
  },
  Skill_132358_EffectNameList = {
    Text = "Алиемус"
  },
  Skill_132358_Name = {
    Text = "Тест·Очнувшись"
  },
  Skill_132359_AwakerSkillBackgroundStory = {
    Text = "Семь цветов света, ослепительных и чарующих～"
  },
  Skill_132359_Desc = {
    Text = "Игрок получает [Power:Arg1] ед. <PowerIconKeywords:силы>, <Block:[Block:Arg2]> ед. щита, [Heal:Arg3] ед. исцеления, [TentaclePower:Arg4] ед. <TentacleInjurieIconKeywords:урона щупальцами>, [Counterattack:Arg5] ед. <RetaliateIconKeywords:контратаки>, наносит <Damage:[Damage:Arg6]> ед. урона [Arg7] раз по врагам в переднем ряду, накладывает [Poison:Arg8] ед. <IntoxicationIconKeywords:отравления>, накладывает [Exhaustion:Arg9] ед. <ExhaustionIconKeywords:истощения>, накладывает [FateCut:Arg10] ед. <CutKeywords:приговора судьбы>."
  },
  Skill_132359_Name = {
    Text = "Красочный ультимейт"
  },
  Skill_132359_OverLimitUtlSkillDesc = {
    Text = "Наносит <Damage:[Damage:Arg1]> единиц <PunctureDamagewords:Прокалывающий Урон>. Израсходуйте до 10 карт \"Деление стрекательных клеток\" из колоды для розыгрыша и сброшенной стопки, каждая из которых наносит 1 дополнительный Урон. Положите 2 карты \"Деление стрекательных клеток\" в руку. Увеличьте Урон, который \"Аурита\" наносит в этом бою, на [Arg2] единиц. Получите [Power:Arg2] очков <PowerIconKeywords:силы> и [TentaclePower:Arg2] очков <TentacleInjurieIconKeywords:Урон шупалец>, после чего за следующие 5 раз, когда вы разыгрываете \"Деление стрекательных клеток\", вы будете вытягивать 1 карту."
  },
