  Skill_132430_AwakerSkillBackgroundStory = {
    Text = "Океан глубокий и тихий, он несет в себе жажду жизни и Страх смерти.\n Но кто-то все равно пытается заполнить море смехом и игрой — когда Аурита делает такое Приглашение, всегда возникает ощущение: \"почему бы не повеселиться с ней\", и просто счастье заполняет грудь."
  },
  Skill_132430_Desc_0 = {
