  Skill_132431_PropertyNameList_0 = {
    Text = "защита*GrowValue1,$GrowValue2"
  },
  Skill_132432_AwakerSkillBackgroundStory = {
    Text = "Дети постепенно проникают в суть сказок и понимают аллегории, стоящие за мифами. В человеческом языке этот процесс называется \"взрослением\".\n Но есть и дети, которые все больше верят в сказки на ночь, они упрямо считают, что на небе действительно есть радуга, и что цивилизации действительно погружены в глубокие моря.\n Аурита любит эти истории, и она хочет поделиться этой радостью с большим количеством друзей."
  },
  Skill_132432_Desc_0 = {
    Text = "<TentacleInjurieIconKeywords:Урон щупальцем> +[TentaclePower:Arg1]. Сбросьте все карты из руки и возьмите столько же карт. Перемешайте 1 карту «Разделение железы» в сброшенную стопку."
  },
  Skill_132432_Desc_1 = {
    Text = "<TentacleInjurieIconKeywords:Урон щупальцем> +[TentaclePower:Arg1]. Сбросьте все карты из руки и возьмите столько же карт +1. Перемешайте 1 карту «Разделение железы» в сброшенную стопку."
  },
  Skill_132432_EffectNameList = {
    Text = "Урон от щупалец, Уровень \"разделение железы\""
  },
  Skill_132432_Name = {
    Text = "Тест·Навык 2"
  },
  Skill_132432_PropertyNameList = {
    Text = "Атакующая Огромная Огромная Огромная Огромная сила*GrowValue1,$GrowValue2"
  },
  Skill_132433_AwakerSkillBackgroundStory = {
    Text = "В мире существует особый вид медузы, который после травмы может вновь развиться в полноценное полип. \n\"Аурита тоже может создавать медуз! Так что Аурита тоже медуза!\"\n На этом этапе познания мира для детей лучше не портить им настроение."
  },
  Skill_132433_Desc_0 = {
    Text = "Наносит <Damage:[Damage:Arg1]> единиц урона. Перемешивает [Arg2] карт \"Железо Центра\" в сброшенную стопку. <RippleKeywords:Эхо>: получает <Energy:[Energy:Arg3]> единиц алиэмиуса."
  },
  Skill_132433_Desc_2 = {
    Text = "Наносит <Damage:[Damage:Arg1]> единиц <PunctureDamagewords:Прокалывающий Урон>. Перемешивает [Arg2] карт \"Деление стрекательных клеток\" в сброшенную стопку. <RippleKeywords:Отголосок>: получает <Energy:[Energy:Arg3]> единиц алиэмиуса."
  },
