  Skill_142700_AwakerSkillBackgroundStory = {
    Text = "«Чего ты хочешь?»\nСилы, порядка, обретения утраченного, мести кровью за кровь…\nОн погрузился в долгое мрачное молчание, хотя ответ у него был давно — ответ без ответа.\nОн хотел, чтобы солнце вставало на востоке и садилось на западе, он хотел, чтобы всё было как обычно."
  },
  Skill_142700_BattleDesc_0 = {
    Text = "Понтос получает <Energy:[Energy:Arg1]> единиц алиемуса. <ExaltIconKeywords:Возвышение гнозиса>: за каждые 3 карты «Раб-измождь» в колоде «Безустанная охота» дополнительно получает 1 заряд <BattueKeywords:Загонной охоты>. За каждую разыгранную карту Понтоса эффект временного снижения силы следующей «Безустанной охоты» повышается на [Arg3]%, не более 3 раз за ход."
  },
  Skill_142700_BattleDesc_15 = {
    Text = "Понт получает <Energy:[Energy:Arg1]> ед. алиемуса. <ExaltIconKeywords:Возвышение>: за каждые 2 карты «Раб-измождь» в колоде «Безустанная охота» дополнительно получает 1 уровень <BattueKeywords:Загонной охоты>. За каждую разыгранную карту Понта эффект снижения временной силы следующей «Безустанной охоты» повышается на [Arg3]%, не более 3 раз за ход. При первом «ударить» и первой «защите» за ход дополнительно получает <Energy:[Energy:Arg4]> ед. алиемуса"
  },
  Skill_142700_Desc_0 = {
    Text = "Понтос получает [Arg2]% базового алиемуса. <ExaltIconKeywords:Возвышение гнозиса>: за каждые 3 карты «Раб-измождь» в колоде «Безустанная охота» получает 1 заряд <BattueKeywords:Загонной охоты>. За каждую разыгранную карту Понтоса эффект временного снижения силы следующей «Безустанной охоты» повышается на [Arg3]%, не более 3 раз за ход."
  },
  Skill_142700_Desc_15 = {
