  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "Жадность — истинная природа человека.\nНикто не способен устоять перед соблазном сладкого, даже сама фея-крёстная.\nКарабу широко ухмыльнулась, обнажив ряд чёрных острых зубов."
  },
  Skill_144491_BattleDesc_0 = {
    Text = "Карабу получает <Energy:[Energy:Arg1]> ед. Алиемуса. <ExaltIconKeywords:Возвышение>: после использования «Багрового горнила» снизить Расход арифметики следующей «Милости чудотворицы» на -3, каждый вариант <FaxianKeywords:Обнаружения> дополнительно содержит 1 карту <DerivativeCardKeywords_152:«Благодати»>, выбрать 1 группу и поместить в Стопку добора."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Карабу получает <Energy:[Energy:Arg1]> ед. Алиемуса. <ExaltIconKeywords:Возвышение>: после использования «Багрового горнила» снизить Расход арифметики следующей «Милости чудотворицы» на -3, каждый вариант <FaxianKeywords:Обнаружения> дополнительно содержит 2 карты <DerivativeCardKeywords_152:«Благодати»>, выбрать 1 группу и поместить в Стопку добора. После розыгрыша «Благодати» Слияние Зародыша +10; чем ниже текущий ОЗ, тем сильнее эффект, максимум до 100%."
  },
  Skill_144491_Desc_0 = {
