  },
  Skill_145674_PropertyNameList = {
    Text = "защита*GrowValue1,$GrowValue2"
  },
  Skill_145675_AwakerSkillBackgroundStory = {
    Text = "По правде говоря, Ожье давно забыл истинный облик того замка.\nНо теперь он может возвести новые бастионы, опираясь на молитву, живущую в глубине его сердца.\nЕсли под его защитой люди всё ещё смогут смеяться и радоваться, а знакомые цветы вновь покроют луга......\nТогда это давно изменившееся сердце всё ещё будет иметь смысл оставаться в этом мире."
  },
  Skill_145675_BattleDesc_0 = {
    Text = "Получить <Block:[Block:Arg1]> единиц Щита, получить [Power:Arg2] единиц <PowerIconKeywords:силы>, потратить все уровни <KuangNu:Тёмного течения> — каждый потраченный уровень увеличивает получаемый Щит и силу на 33%, получить 1 уровень <ShuZui:Самообвинения>."
  },
  Skill_145675_BattleDesc_3 = {
    Text = "Получить <Block:[Block:Arg1]> единиц Щита, получить [Power:Arg2] единиц <PowerIconKeywords:силы>, потратить все уровни <KuangNu2:Тёмного течения> — каждый потраченный уровень увеличивает получаемый Щит и силу на 50%, получить 1 уровень <ShuZui:Самообвинения>."
