  Skill_145676_EffectNameList = {Text = "Урон"},
  Skill_145676_Name = {
    Text = "Оскверняющее Острие"
  },
  Skill_145676_PropertyNameList = {
    Text = "Огромная Огромная Огромная Огромная сила атаки*GrowValue1"
  },
  Skill_145677_AwakerSkillBackgroundStory = {
    Text = "Когда-то юноша пытался содрать с себя эту злобную чёрную грязь — что бы он ни делал: рвал руками, резал острым, бил тупым......невидимый кошмар не желал уходить, а лишь становился всё наглее.\nВ конце концов он признал: они с Ним давно слились в единое целое, неотделимые друг от друга.\nОн стал его тенью."
  },
  Skill_145677_BattleDesc_0 = {
    Text = "Клятвопреступник·Ожье получает <Energy:[Energy:Arg1]> ед. алиемуса. <ExaltIconKeywords:Возвышение>: при первом нанесении урона «Оскверняющим остриём» за ход Клятвопреступник·Ожье накладывает равное количество <Corrosion:Коррозии>. Щит от «Защиты» повышается на 50%, вытянуть 1 карту."
  },
  Skill_145677_BattleDesc_15 = {
    Text = "Клятвопреступник·Ожье получает <Energy:[Energy:Arg1]> ед. алиемуса. <ExaltIconKeywords:Возвышение>: при первом нанесении урона «Оскверняющим остриём» за ход Клятвопреступник·Ожье накладывает равное количество <Corrosion:Коррозии>. Базовый урон «Оскверняющего острия» повышается на 100%, дополнительно получает 200% бонус от силы. Щит от «Защиты» повышается на 100%, вытянуть 1 карту."
  },
  Skill_145677_Desc_0 = {
    Text = "Клятвопреступник·Ожье получает [Arg2]% Основного алиемуса. <ExaltIconKeywords:Возвышение>: при первом нанесении урона «Оскверняющим остриём» за ход Клятвопреступник·Ожье накладывает равное количество <Corrosion:Коррозии>. Щит от «Защиты» повышается на 50%, вытянуть 1 карту."
  },
  Skill_145677_Desc_15 = {
    Text = "Клятвопреступник·Ожье получает [Arg2]% Основного алиемуса. <ExaltIconKeywords:Возвышение>: при первом нанесении урона «Оскверняющим остриём» за ход Клятвопреступник·Ожье накладывает равное количество <Corrosion:Коррозии>. Базовый урон «Оскверняющего острия» повышается на 100%, дополнительно получает 200% бонус от силы. Щит от «Защиты» повышается на 100%, вытянуть 1 карту."
