  },
  Skill_21615_Desc_2 = {
    Text = "Если у вас есть состояние <FragileIconKeywords:хрупкий>, оно будет рассеяно, и вы получите <Block:[Block:Arg3]> и <Block:[Block:Arg1]> очков щита, а также [Power:Arg2] временной <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  Skill_21615_EffectNameList_0 = {
