  Skill_3975_Desc = {
    Text = "Нанести <Damage:[Damage:Arg1]> урона [AttackTimes:Arg2] раз. Применить <FragileIconKeywords:хрупкий> на [Arg3] ходов."
  },
  Skill_3977_AwakerSkillBackgroundStory = {
    Text = "\"Подойди ближе, не стесняйся, дай шляпному господину попробовать твою радость и смех.\"\nМастер Касия слегка приподнял край шляпы, и с громким хлопком из неё вылетела большая связка лент и карт. \n\"Выбери свою карту в сердце. Тсс! Никому не говори. Мастер Касия подскажет, какая из них твоя единственная.\""
  },
  Skill_3977_Desc_0 = {
    Text = "Считается «ударом». Выберите любую 1 карту из <DimensionalSpaceIconKeywords:Ультра пространство> и добавьте её в руку, уменьшив её арифметическую цену на 2. Случайно нанести <Damage:[Damage:Arg1]> урона [Arg2] раз, получить [Power:Arg3] очков временной <PowerIconKeywords:Огромная Огромная сила>."
  },
  Skill_3977_Desc_3 = {
    Text = "Считается «ударом». Выберите любую 1 карту из <DimensionalSpaceIconKeywords:Ультра пространство> и добавьте её в руку, уменьшив расход арифметики на 2. Случайно нанесите <Damage:[Damage:Arg1]> урона [Arg2] раз(а), получите [Power:Arg3] очков временной <PowerIconKeywords:Огромная Огромная сила>. <RippleKeywords:Отголосок>: замешать 1 карту <DerivativeCardKeywords_4:«Вдохновение»> в колоду добора."
