  },
  Skill_3981_PropertyNameList = {
    Text = "Тело*GrowValue2, атакующая Огромная Огромная Огромная Огромная сила*GrowValue1, атакующая Огромная Огромная Огромная Огромная сила*GrowValue3"
  },
  Skill_3982_Desc = {
    Text = "Нанести <Damage:[Damage:Arg1]> урона [AttackTimes:Arg2] раз, добавить в руку 4 карты <DerivativeCardKeywords_24:\"рваная рана\">."
