  Skill_4065_AwakerSkillBackgroundStory = {
    Text = "Верховное зло беспокойно шевелится, но человеческая воля тоже не беззащитна. \n Чёрная слизь, растворяющая всё, ослабила Его дух, став единственной помощью для человечества. \n Мастер кукол на короткое время овладел верхом, она расправила руки, превратив разрушительные электрические потоки в защитные дуги."
  },
  Skill_4065_BattleDesc_0 = {
    Text = "Получите [Arg1] очков временной <AlertIconKeywords:Тревога>. Получите <Posse:[Arg2]> очков ключесвета. Рассеять собственное состояние <FragileIconKeywords:Хрупкость>. Каждый раз, когда Карта попадает в <DimensionalSpaceIconKeywords:Ультра пространство>, превращается в <DerivativeCardKeywords_13:\"Высвобождение: меха\">."
  },
  Skill_4065_BattleDesc_1 = {
    Text = "Получить [Arg1] очков временной <AlertIconKeywords:бдительность>. Получить <Posse:[Arg2]> очков Ключесвет. Рассеять собственное состояние <FragileIconKeywords:хрупкость>. Положить в руку 1 карту «Эрика» с <DepleteIconKeywords:расходом> «защита». Каждый раз, когда Карта попадает в <DimensionalSpaceIconKeywords:Ультра пространство>, трансформироваться в <DerivativeCardKeywords_13:«Высвобождение: меха»>."
  },
  Skill_4065_Desc_0 = {
    Text = "Получите [Arg1] очков временной <AlertIconKeywords:Тревога>. Получите количество серебряной энергии, эквивалентное заряду ключесвета Эрики. Рассеять собственное состояние <FragileIconKeywords:Хрупкость>. Каждый раз, когда Карта попадает в <DimensionalSpaceIconKeywords:Ультра пространство>, превращается в <DerivativeCardKeywords_13:\"Высвобождение: меха\">."
  },
  Skill_4065_Desc_1 = {
    Text = "Получить [Arg1] очков временного <AlertIconKeywords:бдительность>. Получить серебряную энергию, эквивалентную зарядке серебряного ключа Эрики. Удалить собственное состояние <FragileIconKeywords:хрупкость>. Положить в руку 1 карту «защита» Эрики с добавлением <DepleteIconKeywords:расход>. Каждый раз, когда 1 Карта попадает в <DimensionalSpaceIconKeywords:Ультра пространство>, трансформируется в <DerivativeCardKeywords_13:«Высвобождение: меха»>."
