  Skill_4068_AwakerSkillBackgroundStory = {
    Text = "Малышка с детства получала строгое аристократическое образование.\nВсе эти сложные догмы можно свести к одному слову: сдержанность.\nОни включают в себя, но не ограничиваются, осанкой, аппетитом, громкостью речи...\nМалышка целыми днями сидела в цветущем саду, читая стихи, поя и молясь.\nОна чувствовала ужасный голод."
  },
  Skill_4068_BattleDesc_0 = {
    Text = "Потерять [Arg1]%([Arg4]) текущее здоровье. <EmbryoFusionIconKeywords:Эмбриональная фузия>+[Blood:Arg3]. получить [Power:Arg2] единиц временной <PowerIconKeywords:силы>."
