  Skill_4137_AwakerSkillBackgroundStory = {
    Text = "Дедукция — это логическое рассуждение, только поняв правильные предпосылки, можно прийти к точным выводам. \n Прежде чем стать следователем, Рамона всегда использовала дедукцию для познания мира. \n После того как она совершила достаточно много приключений, возможно, она начнёт рассматривать использование индукции."
  },
  Skill_4137_Desc_0 = {
    Text = "Получить <Posse:[Arg1]> очков ключесвета. Выберите 1 карту из колоды для розыгрыша или сброса карт, положите её в руку и установите её цену в арифметике равным 0."
