  Skill_4229_AwakerSkillBackgroundStory = {
    Text = "Филистимский вождь — могущественный воин, который держит гигантский меч и одним взмахом может повалить врага.\nФилистимский вождь — жестокий тиран, он безжалостен и эгоистичен, ради достижения своих целей готов пожертвовать всеми своими соплеменниками.\nПредшественник вождя Филистимлян был рабом своих желаний, он жаждал силы и в конечном итоге оказался в её ловушке."
  },
  Skill_4229_BattleDesc_0 = {
