  },
  Skill_4238_BattleDesc_0 = {
    Text = "Получите <Block:[Block:Arg1]> очков щита. Получите <Energy:[Energy:Arg2]> очков алиэмиус. <RippleKeywords:Эхо>: Управляйте щупальцем для атаки врага."
