  Skill_4289_Name = {Text = "Зонд"},
  Skill_4290_AwakerSkillBackgroundStory = {
    Text = "Триумф всегда был банкетом для римлян.\nБелые голуби, лавровые листья и летящие в воздухе золотые фольги... Всё это связано с воинами, но и не связано.\nОн, вместе с пленными из Галлии, Александры и Парфии, был привязан к тяжелому кресту и выставлен на показ.\nЭто была сохраненная программа триумфа. Воина изощренно высмеивали, потому что он был признан кровавым сообщником покойного императора.\nПозор, Негодование или Досаждение? Нет, ничего из этого.\nУ воина не было эмоций и не было мыслей.\nОн только чувствовал запах крови."
  },
  Skill_4290_BattleDesc_0 = {
    Text = "Увхаш получает <Energy:[Energy:Arg1]> очков Алиемус. <ExaltIconKeywords:Возвышение>: Увхаш не подвержен <CardKeyWord:Запечатывание>, крит. шанс и крит. Урон увеличиваются на [Arg2]%, если Уровень жизни ниже 25%, Эффект удваивается."
  },
  Skill_4290_BattleDesc_15 = {
    Text = "Уухаши получает <Energy:[Energy:Arg1]> ед. ярости. <ExaltIconKeywords:Гностическое пробуждение>: Уухаши не подвержен эффекту <CardKeyWord:Печати>, шанс крит. удара и крит. Урон повышаются на [Arg2]%, итоговый Урон «Песни крови и песка» повышается на [Arg5]%, при здоровье ниже 25% Эффект удваивается."
  },
  Skill_4290_Desc_0 = {
    Text = "Увхаш получает <Energy:[Energy:Arg1]> очков Алиемус. <ExaltIconKeywords:Возвышение>: Увхаш не подвержен <CardKeyWord:Запечатывание>, крит. шанс и крит. Урон увеличиваются на [Arg2]%, если Уровень жизни ниже 25%, Эффект удваивается."
