  Skill_4306_AwakerSkillBackgroundStory = {
    Text = "Она будет действовать на земле во имя Его.\nОна получит заслуженное имя.\nОна будет страдать от боли, которую никто не сможет вынести, в момент разрушения.\nЭто и есть Заместитель."
  },
  Skill_4306_Desc_0 = {
    Text = "Мириам получает <Energy:[Energy:Arg1]> баллов безумия. <ExaltIconKeywords:возжигание ключесвета>: максимум щупалец и количество щупалец +1, накладывает 1 Уровень <WeaknessIconKeywords:слабость> и <VulnerabilityIconKeywords:уязвимость> на всех врагов. Шансы критических ударов \"Удар\" и \"Вершина Жизни\" Мириам увеличиваются на 100%. Поместите 1 карту <O07CardKeyWord4:「путь инаковерия」> в руку."
  },
  Skill_4306_Desc_15 = {
    Text = "Мириам получает <Energy:[Energy:Arg1]> ед. ярости. <ExaltIconKeywords:Гностическое пробуждение>: лимит и количество щупалец +1, накладывает на всех врагов 1 слой <WeaknessIconKeywords:Ослабления> и <VulnerabilityIconKeywords:Уязвимости>. Шанс крит. удара «Удара» и «Высшего жертвоприношения» Мириам повышается на 100%. Помещает 1 карту <O07CardKeyWord4:«Распутье веры»> в руку. За каждые 2 перевёрнутых «Таинства» помещает одну карту «Призрак божественного царства» в руку."
  },
