  Skill_4311_AwakerSkillBackgroundStory = {
    Text = "Нежное прикосновение заставит тебя почувствовать любовь? \n Тёплое дыхание заставит тебя погрузиться в меня? \n Это прикосновение, окружённое жемчугом и лёгким тюлем, для тебя - Подарок?"
  },
  Skill_4311_Desc_0 = {
    Text = "Выберите 1 другое пробуждающее тело, позволяя себе и выбранному пробуждающему телу получить <Energy:[Energy:Arg1]> очков безумия, и [Power:Arg2] очков <PowerIconKeywords:силы>."
