  Skill_4313_Desc = {
    Text = "Нанести [Arg1] слоев<IntoxicationIconKeywords:отравление>."
  },
  Skill_4313_Name = {
    Text = "Токсин"
  },
  Skill_4314_AwakerSkillBackgroundStory = {
    Text = "Её кровь кипит от них, её мозг бурлит от них.\nНеважно, смогут ли эти дети-аберрации исполнить её давнюю мечту, неважно, смогут ли они выжить в Пустоте.\nТаис с любовью встречает каждое Ювенильный Непорочного дитя."
  },
  Skill_4314_Desc_0 = {
    Text = "[<DevouredIconKeywords:Поглощение>: дайте другим пробуждающим телам <Energy:[Energy:Arg1]> очков безумия.] Нанесите <Damage:[Damage:Arg2]> урона всем врагам, нанесите [Arg3] % урона с эффектом <BleedingIconKeywords:кровотечение> и наложите [Arg4] % урона с эффектом <IntoxicationIconKeywords:Яд>, а также получите [Arg5] % урона с эффектом <RetaliateIconKeywords:Контратака>. Выберите 1 непроизводную карту команды из руки, получите [Arg7] базовые копии с добавленными <DepleteIconKeywords:расход> и <NothingnessIconKeywords:Ускользание>, и уменьшите её цену в арифметике на –[Arg6]."
  },
  Skill_4314_EffectNameList = {
    Text = "Безумие, Урон, кровотечение (%), отравление (%), Контратака (%)"
  },
  Skill_4314_Name = {
    Text = "Ритуал изобилия"
  },
  Skill_4314_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Поглощение>: позволить другим пробуждённым получить <Energy:[Energy:Arg1]> очков Алиемуса.] Наносит <Damage:[Damage:Arg2]> единиц урона всем врагам, наносит [Arg3]% урона с эффектом <BleedingIconKeywords:Кровотечение> и накладывает [Arg4]% урона с эффектом <IntoxicationIconKeywords:Яд> и получает [Arg5]% урона с <RetaliateIconKeywords:Контратака>. Выберите 1 непроизводную карту команды из руки, получите [Arg7] базовых копий с добавленным <DepleteIconKeywords:расход> и <NothingnessIconKeywords:Ускользание>, уменьшите её цену в арифметике на [Arg6]. В течение следующих 3 ходов в начале каждого хода превращайте 1 карту «Зародыш» в «Непорочное дитя», если «Зародыш» отсутствует, <EmbryoFusionIconKeywords:Слияние Зародыша> +[Blood:Arg8], не подвержено эффекту усиления Слияния Зародыша."
  },
  Skill_4314_PropertyNameList = {
    Text = "$GrowValue1, атака * $GrowValue2, $GrowValue3, $GrowValue4, $GrowValue5"
  },
  Skill_4315_AwakerSkillBackgroundStory = {
    Text = "Защити меня. Защити меня. Защити меня.\nСлабый монстр, подобно ей, кажется живым, но без сознания.\nЧёрная слизь собирается в её слугу, бесконечно подчиняясь командам, не различая дня и ночи."
  },
  Skill_4315_Desc_0 = {
    Text = "Лили получает <Energy:[Energy:Arg1]> очков Алиемуса. <ExaltIconKeywords:Возвышение>: в начале хода получает 10% макс. ОЗ <PainWord:Выдержка>. Когда Лили накладывает щит, она накладывает [Poison:Arg2] слоев <IntoxicationIconKeywords:Яд> на врага с максимальным здоровьем."
  },
  Skill_4315_Desc_15 = {
    Text = "Лили получает <Energy:[Energy:Arg1]> ед. ярости. <ExaltIconKeywords:Гностическое пробуждение>: в начале хода получает <PainWord:Стойкость> в размере 10% от макс. здоровья. Когда Лили накладывает щит, накладывает [Poison:Arg2] ур. <IntoxicationIconKeywords:Отравления> на врага с наибольшим здоровьем. Взрыв ярости: за каждую полученную в этом ходу атаку Эффект потребления <PainWord:Стойкости> следующего «Карающего удара» повышается на 40%, суммируется до 5 раз."
  },
  Skill_4315_EffectNameList = {
