  Skill_4329_BattleDesc_0 = {
    Text = "Получите <Block:[Block:Arg3]> очков щита, сбросьте все карты в руках. <TransitionIconKeywords:Скачок>: больше не сбрасывайте карты, получите <Block:[Block:Arg4]> очков щита и вытяните 1 карту."
