  Skill_4333_Desc = {
    Text = "Получить [Arg1] ед. <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, получить <Block:[Block:Arg2]> ед. щита."
  },
  Skill_4334_AwakerSkillBackgroundStory = {
    Text = "Цветущий бутон в черной грязи. Он когда-то чувствовал заботу садовода, когда-то купался в дождевых каплях. \n Но в этот момент он одиноко цветет, позволяя буре разрывать нежную кожу, позволяя ливню бить по слабому телу, позволяя тонкому и острому лезвию разрезать поверхность, длинной и острой игле вонзаться в костный мозг. \n В любом случае, тот огромный монстр, который живет в ее теле, защитит ее от боли. \n Возможно, единственным, кто останется рядом с ней, будет этот огромный монстр, и с этого момента ей суждено быть только с монстром..."
  },
  Skill_4334_BattleDesc_0 = {
    Text = "Получить <Block:[Block:Arg1]> очков щита. Ответить <PainWord:Выдержка> уровней [Arg2]%([Arg3]) здоровья и снять <PainWord:Выдержка>. При каждом получении 1 атаки накладывать на атакующего [Poison:Arg4] слоев <IntoxicationIconKeywords:отравление>, длительностью 1 ход."
  },
  Skill_4334_BattleDesc_3 = {
    Text = "Получить <Block:[Block:Arg1]> очков щита. Ответить <PainWord:Выдержка> уровней [Arg2]%([Arg3]) здоровья и убрать половину <PainWord:Выдержка>. Каждый раз, когда вы получаете 1 атаку, наложить [Poison:Arg4] слоев <IntoxicationIconKeywords:отравление> на атакующего, длится 1 ход."
  },
  Skill_4334_Desc_0 = {
    Text = "Получить <Block:[Block:Arg1]> очков щита. Ответить <PainWord:Выдержка> уровней [Arg2]% здоровья и удалить <PainWord:Выдержка>. При каждом получении 1 атаки накладывает на атакующего [Poison:Arg4] слоев <IntoxicationIconKeywords:отравление>, длительностью 1 ход."
  },
  Skill_4334_Desc_3 = {
