  Skill_4339_AwakerSkillBackgroundStory = {
    Text = "Однажды кто-то полушутя спросил Айгис, может ли она связать себе шарф, потому что у неё было всё: от спиц до пряжи. \n Айгис смущённо опустила голову. Она не сказала никому, что спицы на её голове — это не украшение, а специальный инструмент, подавляющий силу её глаз. \n Через несколько дней она закончила цветной шарф, используя одолженные спицы."
  },
  Skill_4339_Desc_0 = {
    Text = "Айгис получает <Energy:[Energy:Arg1]> очков Алиемуса. <ExaltIconKeywords:Возвышение>: после разыгрывания карты Айгис накладывает на всех врагов [Arg2] ход <VulnerabilityIconKeywords:уязвимость>."
  },
  Skill_4339_Desc_15 = {
    Text = "Эгис получает <Energy:[Energy:Arg1]> ед. ярости. <ExaltIconKeywords:Очнувшись гнозиса>: после того как Эгис разыгрывает карту, накладывает на всех врагов <VulnerabilityIconKeywords:уязвимость> на [Arg2] раундов. После применения взрыва ярости Эгис следующая её «защита» срабатывает 3 раза, а также Базовый Урон взрыва ярости увеличивается на 50%."
  },
