  Skill_4368_Name = {Text = "Фунт"},
  Skill_4371_Desc = {
    Text = "Нанести <Damage:[Damage:Arg1]> урона [AttackTimes:Arg2] раз, восстановить жизнь, равную незаблокированному урону. Положить 1 карту <DerivativeCardKeywords_34:\"Боль неутолённого\"> в колоду для розыгрыша."
