  Skill_4383_Name = {Text = "Блеск"},
  Skill_4384_AwakerSkillBackgroundStory = {
    Text = "Чем больше место охвачено воздержанием и подавлением, тем более удивительной становится способность девушки к контролю. \n Громкий звук бичевания равен сладким словам любви, горячие капли воска заменяют обжигающие поцелуи, тугая привязь — это забота до мелочей, а покрасневшие шрамы — доказательство любви. \n В этом трагическом иллюзорном мире цвета меда раздается звонкий смех девушки."
  },
  Skill_4384_Desc_0 = {
    Text = "Нанести всем врагам <Damage:[Damage:Arg1]> урона 2 раза, каждый слой <RetaliateIconKeywords:контратаки> увеличивает Урон на [Arg2] очков. Получить [Power:Arg3] очков <PowerIconKeywords:силы>."
