  Skill_4403_AwakerSkillBackgroundStory = {
    Text = "Бесчисленные шестеренки перекрываются Близкий Близкий Близкий Близкий друг с другом, приводя в движение и наделяя фарфоровый корпус способностью имитировать жизнь.\nЭто её самый удачный проект, непревзойденный и сложный механизм.\nЭрика не могла и представить, что эта автоматическая кукла, названная в её честь, станет её Часть 2 жизнью."
  },
  Skill_4403_Desc_0 = {
    Text = "Эрика получает <Energy:[Energy:Arg1]> очков Алиемуса. <ExaltIconKeywords:Возвышение>: когда Эрика наносит Урон, она получает [Power:Arg2] временных очков <PowerIconKeywords:силы>; когда Эрика применяет щит, она получает [Arg3] временных очков <AlertIconKeywords:Тревога>."
  },
  Skill_4403_Desc_15 = {
