  Skill_4442_Name = {Text = "Фунт"},
  Skill_4443_AwakerSkillBackgroundStory = {
    Text = "Она когда-то упала с вершины, и прежняя слава превратилась в сегодняшнее позор. \n После изгнания из дворца Леди Регент, Илот стала одной из многих обычных рабынь, подвергаясь избиениям спартанскими тюремщиками. В такой безвыходной ситуации она никогда не впадала в уныние и апатию. \n В её груди горит лишь непрекращающаяся Досаждение. \n Цепи с шипами на её шее были безжалостно разорваны, и Огромная Огромная Огромная Огромная сила, которая сковывала её, была освобождена, истинное лицо скоро будет раскрыто. \n С этого момента, пожалуйста, каждый день очищай свою шею и жди моей мести."
  },
  Skill_4443_Desc = {
    Text = "\"<DevouredIconKeywords:Поглощение>: Вытяните [Arg1] карты \"ударить\", временный лимит руки +2, Базовый Урон \"ударить\" Илота в этом бою увеличивается на [Arg3]%.\" Рассеивает собственное состояние <WeaknessIconKeywords:слабость> и временное <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, снижая его, в этом ходу Урон от \"ударить\" увеличивается на [Arg2]%, Урон, нанесённый Илотом, увеличивается на [Arg4]%."
  },
