  Skill_4458_AwakerSkillBackgroundStory = {
    Text = "Он гордо демонстрирует свои шрамы: глубокие — от боёв на поле, мелкие — от повседневных тренировок и поединков.\n Это доказательства его геройства, его Надменность.\n Но не спрашивайте о шрамах на его шее, это Начало его силы и Генезис его позора."
  },
  Skill_4458_Desc_0 = {
    Text = "Голиаф получает <Energy:[Energy:Arg1]> очков алиемуса. <ExaltIconKeywords:Возвышение>: получает 1 щупальце, когда Голиаф наносит Урон, получает [Power:Arg2] очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> и [TentaclePower:Arg3] очков <TentacleInjurieIconKeywords:Урон шупалец>."
  },
  Skill_4458_Desc_15 = {
    Text = "Голиаф получает <Energy:[Energy:Arg1]> ед. ярости. <ExaltIconKeywords:Очнувшись гнозиса>: получает 1 щупальце, когда Голиаф наносит Урон, получает [Power:Arg2] ед. <PowerIconKeywords:силы> и [TentaclePower:Arg3] ед. <TentacleInjurieIconKeywords:урона щупальцами>. Голиаф в стойке бурного прилива дополнительно получает [Arg4] % бонус к силе."
