  Skill_4576_AwakerSkillBackgroundStory = {
    Text = "Принеси мне свою голову.\nОна станет одной из моих любимых коллекций, плавающих в океане размерности.\nОхотница за черепами приподняла уголки губ и беззаботно сказала.\n\"Если повезёт, она сможет всегда быть рядом со мной, как и они?\""
  },
  Skill_4576_BattleDesc_0 = {
    Text = "Наносит <Damage:[Damage:Arg1]> Урон самому слабому врагу, Огромная Огромная Огромная Огромная сила оказывает 5-кратное воздействие на \"Охотница за головами\". После убийства врага любым способом Даффодил постоянно увеличивает Базовый Урон \"Охотница за головами\" на 25% в текущем уровне (текущий [Arg3] раз). <TransitionIconKeywords:Скачок>: изменить на нанесение <Damage:[Damage:Arg2]> урона самому сильному врагу."
  },
  Skill_4576_Desc_0 = {
    Text = "Наносит <Damage:[Damage:Arg1]> урона самому слабому врагу, Огромная Огромная Огромная Огромная сила в \"Охотница за головами\" увеличивается в 5 раз. После убийства врага Давдейл любым способом, Базовый Урон от \"Охотница за головами\" увеличивается на 25% навсегда в текущем уровне. <TransitionIconKeywords:Скачок>: изменить на нанесение <Damage:[Damage:Arg2]> урона самому сильному врагу."
  },
  Skill_4576_EffectNameList = {
