  Skill_4643_AwakerSkillBackgroundStory = {
    Text = "\"Нет, нет. Это не логика творчества.\"\nСкульптор произнес это с низким голосом, но не осмелился взглянуть в глаза своему молодому ученику.\nКаковы же это были глаза —\nтихие, как Океан на краю мира, в которых отражалась Рождённый войной умирающих птиц.\nОна знала всё, но молчала."
  },
  Skill_4643_BattleDesc_0 = {
    Text = "Получите <Block:[Block:Arg1]> очков щита. Получите [Arg2] щупалец. <RippleKeywords:эхо>: получите <Energy:[Energy:Arg4]> очков алиемус."
