  Skill_4659_tempBattleDesc_2 = {
    Text = "Получить <Block:[Block:Arg1]> ед. щита. Получить <Energy:[Energy:Arg2]> ед. ярости. Следующий «Клинок дерзости» в этом ходу срабатывает 2 раза."
  },
  Skill_4660_AwakerSkillBackgroundStory = {
    Text = "Один-два, один-два... \n Она, держа поднос, шагала в быстром ритме сквозь толпу. \n Гости неустанно пили и пели, она без усталости подавала блюда и улыбалась. \n Здесь всё золотое. Золотой зал, золотое Прекрасное Прекрасное Прекрасное Прекрасное вино и золотые юбки. \n Карен любит золото. Она подняла свою фирменную улыбку, отработанную бесчисленное количество раз. \n \"Гость, пожалуйста, не торопитесь —!!\""
  },
  Skill_4660_Desc_0 = {
    Text = "Уберите состояние <SlowIconKeywords:замедление> со всех карт в руке. Восстановите <Heal:[Heal:Arg1]> очков жизни. Положите в руку 1 карту <DerivativeCardKeywords_42:\"Изумительная кухня\">. Нанесите всем врагам [Poison:Arg2] уровней <IntoxicationIconKeywords:яд>."
  },
  Skill_4660_Desc_3 = {
    Text = "Уберите состояние <SlowIconKeywords:замедление> со всех карт в руке. Восстановите <Heal:[Heal:Arg1]> очков здоровья. Положите в руку 1 карту <DerivativeCardKeywords_43:\"Изумительная кухня\">. Нанесите всем врагам [Poison:Arg2] уровней <IntoxicationIconKeywords:яд>."
