  Skill_4661_Desc = {
    Text = "Нанести <Damage:[Damage:Arg1]> урона [AttackTimes:Arg2] раз, получить [Arg3] уровней временной <RetaliateIconKeywords:контратаки>."
  },
  Skill_4661_Name = {
    Text = "Трагедия в медовых тонах"
  },
  Skill_4662_AwakerSkillBackgroundStory = {
    Text = "Люди восхищаются её красотой, завидуют её обаянию, но никто не воспринимает бутон цветка всерьёз. \n Непостоянный бутон, колеблющийся на полях, произвольно управляемый будущим, рассматривается как ставка для повышения в должности цветовода. \n Только когда она расцветает перед короной, люди вдруг осознают, что сами уже изранены до крови от зацепок."
  },
  Skill_4662_BattleDesc_0 = {
    Text = "Наносит случайный <Damage:[Damage:Arg1]> Урон [Arg3] раз. В конце хода восстанавливает <Heal:[Heal:Arg2]> очков жизни."
  },
  Skill_4662_BattleDesc_2 = {
    Text = "Случайно наносит <Damage:[Damage:Arg1]> урона [Arg3] раз. За каждое нанесение урона временный критический шанс +5%. В конце хода восстанавливает <Heal:[Heal:Arg2]> единиц жизни."
  },
  Skill_4662_Desc_0 = {
    Text = "Наносит случайный <Damage:[Damage:Arg1]> Урон [Arg3] раз. В конце хода восстанавливает <Heal:[Heal:Arg2]> очков жизни."
  },
  Skill_4662_Desc_2 = {
    Text = "Случайное нанесение <Damage:[Damage:Arg1]> урона [Arg3] раза, каждое нанесение урона увеличивает временный критический шанс на 5%. В конце хода восстановите <Heal:[Heal:Arg2]> очков жизни"
  },
  Skill_4662_EffectNameList_0 = {
    Text = "Урон,Лечение"
