  Skill_4662_Name = {
    Text = "Изящество роз"
  },
  Skill_4662_PropertyNameList_0 = {
    Text = "Атакующая Огромная Огромная Огромная Огромная сила*GrowValue1; телосложение*GrowValue2"
  },
  Skill_4663_AwakerSkillBackgroundStory = {
    Text = "Холодный механизм заменил сердце, а масло в гидравлических трубках заменило кровь. Она должна быть холодной, разумной и действовать в соответствии с командами.\n Но чуждая воля тихо двигалась внутри её оболочки. Ему не нужна кровь, не нужна температура, он может сам разжигать нечеловеческую злобу. Он сказал: покорись, жалкое и слабое существо, а затем уничтожься в моем раскаленном электрическом шаре."
  },
  Skill_4663_BattleDesc_0 = {
    Text = "Получите [Power:Arg1] временных <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Получите <Posse:[Arg2]> очков ключесвета. Рассеять собственное состояние <WeaknessIconKeywords:Слабость>. Каждый раз, когда Карта попадает в <DimensionalSpaceIconKeywords:Ультра пространство>, превращается в <DerivativeCardKeywords_14:\"Механическое вооружение: Сбор\">."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "Получите [Power:Arg1] временных <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Получите <Posse:[Arg2]> очков Ключесвет. Рассеять собственное состояние <WeaknessIconKeywords:Слабость>. Поместите в руку 1 карту \"Удар\", прикреплённую к Эрике с <DepleteIconKeywords:расход>. Каждый раз, когда Карта попадает в <DimensionalSpaceIconKeywords:Ультра пространство>, превращается в <DerivativeCardKeywords_14:\"Ограничение: меха\">."
  },
  Skill_4663_Desc_0 = {
    Text = "Получите [Power:Arg1] временных <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Получите ключесвет, равный восстановлению ключесвета Эрики. Рассеять собственное состояние <WeaknessIconKeywords:слабость>. Каждый раз, когда 1 Карта попадает в <DimensionalSpaceIconKeywords:Ультра пространство>, трансформироваться в <DerivativeCardKeywords_14:\"Механическое вооружение-Ограничение\">."
  },
  Skill_4663_Desc_1 = {
    Text = "Получите [Power:Arg1] временных <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Получите количество ключесвета, эквивалентное заряду ключесвета Эрики. Рассеять собственное состояние <WeaknessIconKeywords:Слабость>. Поместите в руку 1 карту \"ударить\" с <DepleteIconKeywords:расход> Эрики. Каждый раз, когда Карта попадает в <DimensionalSpaceIconKeywords:Ультра пространство>, превращается в <DerivativeCardKeywords_14:\"Механическое вооружение: Сбор\">."
  },
