  Skill_4664_AwakerSkillBackgroundStory = {
    Text = "Невидимая болезнь тихо проникает, принося бесконечные страдания и безумие. \n\nЕпископ не может уснуть ночью, глубоко скорбя о том, что не может избавить людей от страданий. \n\n\"О, Милосердный Творец, спаси их, я готов взять на себя все страдания и печали.\" \n\nИ вот Бог-Отец послал ему \"благодать\", позволив ему держать плиту с высеченным Словом Божиим, чтобы совершать дела избавления от страданий."
  },
  Skill_4664_Desc_0 = {
    Text = "Сальвадор получает <Energy:[Energy:Arg1]> очков Алиемуса. <ExaltIconKeywords:Гнозис>: положите 1 карту <B02AFKeyWord:Святыня милосердия> в руку. В конце хода получите [Power:Arg2] очков <PowerIconKeywords:силы>."
  },
  Skill_4664_Desc_15 = {
    Text = "Сальвадор получает <Energy:[Energy:Arg1]> ед. безумия. <ExaltIconKeywords:Очнувшись Гнозиса>: помещает 1 карту <B02AFKeyWord:защита милосердием> в руку. В конце хода получает [Power:Arg2] ед. <PowerIconKeywords:Силы>. Накопление Багровой печи от «Покровительства Создателя» и «Благословенной крови» увеличивается на 25%, при выборе «Отпущения» в «Страдании, что должно быть искуплено» Эффект увеличения итогового урона за каждый потраченный 1% макс. здоровья Багровой печи повышается с 2% до 5%."
  },
  Skill_4664_EffectNameList = {
    Text = "Безумие, Огромная Огромная Огромная Огромная сила"
  },
