    Text = "\"Фу, пусть я, девушка, как следует тебя проучу.\""
  },
  Skill_4666_BattleDesc_0 = {
    Text = "Нанести <Damage:[Damage:Arg1]> урона. Получить <Energy:[Energy:Arg2]> очков безумия."
  },
  Skill_4666_BattleDesc_2 = {
    Text = "Наносит <Damage:[Damage:Arg1]> единиц урона. Получает <Energy:[Energy:Arg2]> единиц алиэмиуса. <TentacleInjurieIconKeywords:Урон щупальцем> +[TentaclePower:Arg3]."
  },
  Skill_4666_Desc_0 = {
