  Skill_4701_AwakerSkillBackgroundStory = {
    Text = "Это искажённый эмбрион, это семя зла.\nЭто подстрекающее сердцебиение, это бурный пульс, это Досаждение между кровью и плотью, это запутанная Колесо Судьбы.\nПо образу и подобию не обладает свободой выбора, она может лишь позволить искажённому зачатию развиваться."
  },
  Skill_4701_Desc_0 = {
