  Skill_4727_Name = {Text = "Укус"},
  Skill_4728_AwakerSkillBackgroundStory = {
    Text = "Я уже отказался от всего человеческого! Я вернусь в объятия глубокого моря!\nНо почему моя Метаморфоза провалилась?\nЭто насмешка судьбы? Или моя глупость?\nСумасшедший Цек обнимает сломанный гарпун, пытаясь погрузиться на дно моря.\nЛишь бы вернуться, быть принятым, независимо от того, сколько преград впереди, он уберет их одну за другой."
  },
  Skill_4728_Desc_0 = {
