  Skill_47455_Name_1 = {
    Text = "Мешок с песком"
  },
  Skill_4745_AwakerSkillBackgroundStory = {
    Text = "Два волевых начала постоянно противостоят и борются в механическом теле: одно стремится к разрушению, другое не желает подчиняться. Но ничтожному человеку невозможно долго одерживать победу, она в конечном итоге будет поглощена, став безумным сосудом, существующим лишь для разрушения.\n Поэтому она выпустила весь электрический ток. Огромные электрические дуги окутали её, короткое замыкание тела издавало гремящий звук тока, она бросила накопленную энергию вперёд, а затем погрузилась в кратковременное состояние недееспособности. \n \"Не в состоянии двигаться, не в состоянии разрушать.\""
  },
  Skill_4745_Desc_0 = {
