  Skill_4749_Desc = {
    Text = "Наносить <Damage:[Damage:Arg1]> единиц урона [AttackTimes:Arg2] раз."
  },
  Skill_4750_AwakerSkillBackgroundStory = {
    Text = "Зачатие, пусть родится, пусть Размножение. \n В этом постепенно растворяющемся реальности, в погружающемся в темноту мире, в грядущем новорождённом вакууме. \n Ваше существование — это плод жертвоприношения матери, это причина существования матери. \n Непорочное дитя, возродись в новом мире — в том непорочном, что уничтожило весь Страх, возродись в новом мире."
  },
  Skill_4750_Desc_0 = {
    Text = "Таис получает <Energy:[Energy:Arg1]> очков Алиемуса. <ExaltIconKeywords:Возвышение>: немедленно получите 1 карту <DerivativeCardKeywords_10:Непорочное дитя>. Каждый раз, когда вы освобождаете Призыв, преобразуйте один Зародыш из руки в <DerivativeCardKeywords_10:Непорочное дитя>."
  },
  Skill_4750_Desc_15 = {
    Text = "Тэйсы получает <Energy:[Energy:Arg1]> ед. ярости. <ExaltIconKeywords:Гностическое пробуждение>: немедленно получает 1 карту <DerivativeCardKeywords_10:Святое дитя>. При каждом использовании ключ-приказа превращает один эмбрион в руке в <DerivativeCardKeywords_10:Святое дитя>. «Обряд изобилия» дополнительно помещает 1 копию в руку."
  },
