  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "В бесконечных скитаниях Тинкт уже забыла имя своей родины.\nЗа долгие годы космос уже забыл имя той погибшей планеты.\nОна, как и бесчисленные растёртые и брошенные планеты, называется \"Пустой звёздой\". \nЕё пение, возможно, является последним остаточным звуком той планеты за пределами."
  },
  Skill_4822_Desc_0 = {
    Text = "Тинкт получает <Energy:[Energy:Arg1]> единиц Алиемуса. <ExaltIconKeywords:Возвышение>: увеличивает Базовый Урон Тинка \"ударить\" на [Arg2]%, все карты Тинка получают 1 случайный Эффект, который будет удалён в конце боя."
