  Skill_4858_AwakerSkillBackgroundStory = {
    Text = "Девушка с грустью покинула обанкротившийся аквариум, но в качестве платы за работу ей разрешили забрать нескольких медуз домой.  \nЭто были её любимые маленькие создания — духи морских глубин, вечные цветы жизни.  \nСтоило только заботиться о них с любовью, и они могли наполнить весь аквариум! — о таком она когда-то мечтала.  ."
  },
  Skill_4858_Desc_0 = {
    Text = "Аурита получает <Energy:[Energy:Arg1]> очков алиемуса. <ExaltIconKeywords:Возвышение>: получает 1 щупальце и помещает 2 карты \"Деление стрекательных клеток\" в руку. Когда Аурита наносит Урон, [Arg2] щупальца атакуют 1 раз."
