  Skill_57338_Desc_0 = {
    Text = "Добавить в Руку 3 карты <DerivativeCardKeywords_17:«Владычество клинка»> с Базовым уроном +400% и расходом арифметики 0, получить временную <PowerIconKeywords:Силу>, равную [Arg1]% урона щупалец."
  },
  Skill_57338_Desc_3 = {
    Text = "Положите 3 карты с увеличением базового урона на 400% и ценой арифметики 0 <DerivativeCardKeywords_17:\"Владычество клинка\"> в руку, получите временную <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, равную [Arg1]% ущерба от щупалец. Голиаф получает [Arg2]% временного критического шанса."
