  Skill_57670_Name = {
    Text = "Устарелый"
  },
  Skill_57671_Desc = {
    Text = "Получить [Arg1] очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Разделяется на \"Дитя света\" и \"сын тьмы\", каждые 1% степени слияния уменьшают жизнь \"Дитя света\" на 0.5%."
