  Skill_57887_Name = {
    Text = "Идеальное Слияние"
  },
  Skill_57888_Desc = {
    Text = "Получить [Arg1] очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Разделение на \"сын тьмы\" и \"Дитя света\", при этом жизнь \"Сына Света\" уменьшается на 75%, и он получает постоянное ошеломление."
  },
  Skill_57888_Name = {
    Text = "Фрактал Растворения"
