  Skill_57892_Desc = {
    Text = "Поместите 3 карты \"<DerivativeCardKeywords_1:Эхо призрачного образа>\" в руку. После выбора удалите эту опцию."
  },
  Skill_57892_Name = {
    Text = "Поиск Пути Вперёд"
  },
  Skill_57893_Desc = {
    Text = "Получите исходные копии 3 различных карт команды, сыгранных в конце прошлого хода, с расходом арифметики 0. Добавьте карту \"<DerivativeCardKeywords_39:Эхо Прошлого>\" в руку. После выбора удалите эту опцию."
  },
  Skill_57893_Name = {
    Text = "Вспомнить Прошлое"
  },
  Skill_57894_Desc = {
    Text = "Поместите \"<DerivativeCardKeywords_67:Серебряный Погоня за светом ключа>\" и \"<DerivativeCardKeywords_41:Резонанс Серебряного Ключа>\" в руку, выберите, затем удалите эту опцию."
  },
