  Skill_70014_Desc = {
    Text = "Расход 10 очков \"Абиссальной энергии\", поместите 1 карту <DerivativeCardKeywords_60:\"Независимый\"> в руку, крит. шанс и крит. Урон всех пробуждённых увеличиваются на 25％."
