  Skill_78782_AwakerSkillBackgroundStory = {
    Text = "В покачивающихся маятниках мир начинает стираться.\nВ твоих глазах, в твоем сердце, внутри твоей головы остался только один силуэт.\nЭто искупление, но также и Тупик."
  },
  Skill_78782_BattleDesc = {
    Text = "Восстановить <Heal:[Heal:Arg1]> очков жизни [Arg2] раз, временно удаляет все состояния <MadnessIconKeywords:сумасшествие> у врагов и временно снижает их силу на [Exhaustion:Arg3] очков <ExhaustionIconKeywords:Огромная Огромная сила>. <WormholeKeywords:Квазар>: получить [Power:Arg4] очков <PowerIconKeywords:Огромная Огромная сила>."
  },
  Skill_78782_Desc = {
