  Skill_89776_AwakerSkillBackgroundStory = {
    Text = "\"Брат, ты говоришь, что можно летать на крыльях, летать и летать, насколько высоко можно взлететь? Можно ли долететь до облаков, прикоснуться к Луне и звёздам?\"\n\"Возможно... можно? Тогда нам нужны большие и сильные крылья.\"\nГлубокая и мечтательная галактика с созвездиями на странице рукописи отражалась в сладком сне двух детей, превращаясь в семечко желания, зарытое в их сердцах."
  },
  Skill_89776_Desc_0 = {
    Text = "Кастор получает <Energy:[Energy:Arg1]> очков алиемуса. <ExaltIconKeywords:Возвышение>:Урон от Кастора всегда наносит крит. Удар, после разыгрывания «<DerivativeCardKeywords_107:Ониксовое перо>» на цель накладывается [Corrosion:Arg2] слоёв <Corrosion:Коррозии>, сохраняемый щит повышается на 50%."
  },
  Skill_89776_Desc_15 = {
    Text = "Кастор получает <Energy:[Energy:Arg1]> очков алиемуса. <ExaltIconKeywords:Возвышение>:Урон от Кастора всегда наносит крит. Удар, после разыгрывания «<DerivativeCardKeywords_107:Ониксовое перо>» на цель накладывается [Corrosion:Arg2] слоёв <Corrosion:Коррозии>, сохраняемый щит повышается на 50%. При первом разыгрывании Ониксового пера за ход наносит врагам в переднем ряду коррозию, равную таланту «Священные перья очищения», потеря ОЗ при снятии коррозии повышается с 300% до 500%."
  },
  Skill_89776_EffectNameList = {
    Text = "Алиэмиус,Эрозия"
  },
