  Skill_95811_AwakerSkillBackgroundStory = {
    Text = "Бумага приглашения сделана из мягкой кожи. Украшение приглашения сделано из гладкого черепа. Текст приглашения написан свежей кровью. Подпись приглашения принадлежит горячему хозяину королевского поместья.\nДоресайн посылает вам искреннее Приглашение посетить этот банкет, принадлежащий вам."
  },
  Skill_95811_Desc_0 = {
    Text = "Доресайн получает <Energy:[Energy:Arg1]> ед. Алиемуса. <ExaltIconKeywords:Возвышение>: получить [Power:Arg2] ед. <PowerIconKeywords:Силы>, урон Доресайна дополнительно усиливается на [Arg3]% от Силы. После первого убийства за ход Доресайн наносит другим врагам <FixedDamage:Чистый урон> в размере 50% избыточного урона."
  },
  Skill_95811_Desc_15 = {
    Text = "Доресайн получает <Energy:[Energy:Arg1]> ед. Алиемуса. <ExaltIconKeywords:Возвышение>: получить [Power:Arg2] ед. <PowerIconKeywords:Силы>, урон Доресайна дополнительно усиливается на [Arg3]% от Силы. Нанести всем врагам <FixedDamage:Чистый урон> в размере [Arg4]% текущих ОЗ. После первого убийства за ход Доресайн наносит другим врагам <FixedDamage:Чистый урон> в размере 100% избыточного урона."
